#!/bin/bash\n\n# Disbursement Roll Migration Test Script\necho \"🚀 Disbursement Roll Migration Tester\"\necho \"====================================\"\n\n# Configuration\nBASE_URL=\"http://localhost:5000/api/v1\"\n\n# Step 1: Test server health\necho \"\\n1️⃣ Testing server health...\"\nHEALTH_RESPONSE=$(curl -s -w \"%{http_code}\" \"$BASE_URL/health\")\nHTTP_CODE=\"${HEALTH_RESPONSE: -3}\"\n\nif [ \"$HTTP_CODE\" != \"200\" ]; then\n    echo \"❌ Server is not responding (HTTP $HTTP_CODE)\"\n    echo \"Make sure the server is running on port 5000\"\n    exit 1\nfi\necho \"✅ Server is healthy!\"\n\n# Step 2: Get login credentials\necho \"\\n2️⃣ Please provide login credentials:\"\nread -p \"📧 Email: \" EMAIL\nread -s -p \"🔑 Password: \" PASSWORD\necho\n\n# Step 3: Login to get token\necho \"\\n3️⃣ Logging in...\"\nLOGIN_RESPONSE=$(curl -s -X POST \"$BASE_URL/auth/login\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\\\"email\\\":\\\"$EMAIL\\\",\\\"password\\\":\\\"$PASSWORD\\\"}\")\n\nTOKEN=$(echo $LOGIN_RESPONSE | grep -o '\"token\":\"[^\"]*' | cut -d'\"' -f4)\n\nif [ -z \"$TOKEN\" ]; then\n    echo \"❌ Login failed. Please check your credentials.\"\n    echo \"Response: $LOGIN_RESPONSE\"\n    exit 1\nfi\necho \"✅ Login successful!\"\n\n# Step 4: Get branch ID (optional)\necho \"\\n4️⃣ Branch Information:\"\nread -p \"🏢 Branch ID (optional, press Enter to skip): \" BRANCH_ID\n\n# Step 5: Get current disbursement roll\necho \"\\n5️⃣ Getting current disbursement roll...\"\nif [ -n \"$BRANCH_ID\" ]; then\n    QUERY=\"?branchId=$BRANCH_ID\"\nelse\n    QUERY=\"\"\nfi\n\nCURRENT_ROLL=$(curl -s -X GET \"$BASE_URL/disbursement-roll$QUERY\" \\\n  -H \"Authorization: Bearer $TOKEN\" \\\n  -H \"Content-Type: application/json\")\n\necho \"📄 Current Roll: $CURRENT_ROLL\"\n\n# Step 6: Run migration\necho \"\\n6️⃣ Running migration...\"\nMIGRATION_RESPONSE=$(curl -s -X POST \"$BASE_URL/disbursement-roll/migrate\" \\\n  -H \"Authorization: Bearer $TOKEN\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{}\")\n\necho \"📄 Migration Response: $MIGRATION_RESPONSE\"\n\n# Check if migration was successful\nif echo \"$MIGRATION_RESPONSE\" | grep -q '\"success\":true'; then\n    echo \"✅ Migration completed successfully!\"\nelse\n    echo \"❌ Migration failed\"\nfi\n\n# Step 7: Get updated disbursement roll\necho \"\\n7️⃣ Getting disbursement roll after migration...\"\nUPDATED_ROLL=$(curl -s -X GET \"$BASE_URL/disbursement-roll$QUERY\" \\\n  -H \"Authorization: Bearer $TOKEN\" \\\n  -H \"Content-Type: application/json\")\n\necho \"📄 Updated Roll: $UPDATED_ROLL\"\n\necho \"\\n🎉 Test completed!\"\necho \"\\n📊 Summary:\"\necho \"Before: $CURRENT_ROLL\"\necho \"After:  $UPDATED_ROLL\"